&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Previous sales experience in cell therapy/bone marrow transplant&amp;nbsp;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;
